using System;
using System.Linq;
using System.Text;
using Newtonsoft.Json.Linq;
namespace RoomLab.Native
{
    public static class NativeAuthoredIceChecks
    {
        public static NativeMotion Intro(NativeProject project){var room=project.Courses[0].Rooms.Find(r=>r.Name=="冰引入");if(room==null)throw new Exception("Missing authored ice room");return new NativeMotion(project,project.Courses[0].Id,room.Id,NativeGameplayRules.Editor255Compat);}
        public static void StepOnControl(NativeMotion g){var control=g.Room.Objects.Find(o=>o.Type=="physics.thermal");g.Mode="playing";g.RespawnRemaining=0;g.Player.x=control.X*32+4;g.Player.y=control.Y*32-29;g.Player.vx=0;g.Player.vy=120;g.Player.grounded=false;g.Tick(NativeMotion.Step);g.Tick(NativeMotion.Step);}
        public static int Run(NativeProject project){int n=0;void Check(bool b,string m){n++;if(!b)throw new Exception("Authored ice: "+m);}var g=Intro(project);var ice=g.Room.Objects.FindAll(o=>o.Type=="physics.ice");Check(ice.Count==42,"42 source ice instances");var control=g.Room.Objects.Find(o=>o.Type=="physics.thermal");Check(control.Text("initialState")=="inherit"&&(string)control.Trigger["mode"]=="foot","source thermal properties unchanged");Check(ice.All(o=>g.TemperatureAt(o)=="hot"&&!g.ObjectStates[o.Id].solid),"initial hot ice must be absent");Check(!g.CollisionRects.Any(c=>ice.Exists(o=>o.Id==c.id)),"hot ice has no collision");StepOnControl(g);Check(ice.All(o=>g.TemperatureAt(o)=="cold"&&g.ObjectStates[o.Id].solid),"real foot input produces cold solid ice");Check(g.CollisionRects.Count(c=>ice.Exists(o=>o.Id==c.id))==42,"42 cold colliders");
            for(int i=0;i<150;i++)g.Tick(NativeMotion.Step);Check(g.TemperatureAt(ice[0])=="cold","standing contact does not retrigger");
            var platform=ice.Find(o=>g.SafePosition(o.X*32+4,o.Y*32-28));Check(platform!=null,"safe ice standing position");g.Player.x=platform.X*32+4;g.Player.y=platform.Y*32-28;g.Player.vx=g.Player.vy=0;g.Player.grounded=true;g.Player.support=platform.Id;g.Tick(NativeMotion.Step);Check(g.Player.support==platform.Id,"player actually stands on ice");int cracking=(int)Math.Ceiling(platform.Number("meltAfter",5)*.65/NativeMotion.Step);for(int i=0;i<cracking;i++)g.Tick(NativeMotion.Step);Check(g.VisualState(platform)=="cracked","instance standing time cracks");int extra=(int)Math.Ceiling(platform.Number("meltAfter",5)*.4/NativeMotion.Step);for(int i=0;i<extra;i++)g.Tick(NativeMotion.Step);Check(!g.ObjectStates[platform.Id].solid,"instance standing time melts");g.Player.x=g.Entry.X*32+4;g.Player.y=g.Entry.Y*32+4;g.Player.grounded=false;g.Player.support=null;for(int i=0;i<(int)Math.Ceiling(platform.Number("respawnDelay",1)/NativeMotion.Step)+2;i++)g.Tick(NativeMotion.Step);Check(g.ObjectStates[platform.Id].solid,"instance respawn time regenerates");
            g.Player.x=g.Entry.X*32+4;g.Player.y=g.Entry.Y*32+4;for(int i=0;i<150;i++)g.Tick(NativeMotion.Step);StepOnControl(g);Check(ice.All(o=>g.TemperatureAt(o)=="hot"&&!g.ObjectStates[o.Id].solid),"second separate contact returns hot and removes ice");
            var parkour=project.Courses[0].Rooms.Find(r=>r.Name.Replace(" ","")=="冰跑酷");Check(parkour.Objects.Count(o=>o.Type=="physics.ice"&&o.Number("meltAfter")==5&&o.Number("respawnDelay")==1)==25&&parkour.Objects.Count(o=>o.Type=="physics.ice"&&o.Number("meltAfter")==1&&o.Number("respawnDelay")==1)==1,"26 author 5s/1s instances preserved");
            var restarted=Intro(project);StepOnControl(restarted);restarted.Player.x=restarted.Entry.X*32+4;restarted.Player.y=restarted.Entry.Y*32+4;var restored=NativeMotion.FromContinuation(project,restarted.ExportContinuation(),NativeGameplayRules.Editor255Compat);Check(restored.Room.Zones.All(z=>restored.Zones[z.Id]==restored.Checkpoint.state.zones[z.Id]),"Continue restores checkpoint zone state");Check(restored.Room.Objects.Where(o=>o.Type=="physics.ice").All(o=>restored.ObjectStates[o.Id].solid==restored.Checkpoint.state.objects[o.Id].solid),"Continue restores ice with thermal state");restarted.Retry();Check(ice.All(o=>!restarted.ObjectStates[o.Id].solid&&restarted.TemperatureAt(o)=="hot"),"Retry restores author's initial hot checkpoint");
            foreach(string policy in new[]{"checkpoint","life","initial","preserve"}){var raw=(JObject)project.OriginalJson.DeepClone();foreach(JObject c in (JArray)raw["courses"])foreach(JObject room in (JArray)c["rooms"])foreach(JObject o in (JArray)room["objects"])if((string)o["id"]==control.Id)o["resetPolicy"]=policy;var fixture=NativeProjectLoader.LoadBytes(Encoding.UTF8.GetBytes(raw.ToString()),"json",new ImportOptions{Profile=ImportProfile.EditorAuto});var state=Intro(fixture);StepOnControl(state);var continued=NativeMotion.FromContinuation(fixture,state.ExportContinuation(),NativeGameplayRules.Editor255Compat);string expected=policy=="preserve"?"cold":"hot";Check(continued.TemperatureAt(continued.Room.Objects.Find(o=>o.Id==ice[0].Id))==expected,"Continue resetPolicy "+policy);Check(continued.ObjectStates[ice[0].Id].solid==(expected=="cold"),"Continue ice/thermal sync "+policy);state.Retry();Check(state.TemperatureAt(state.Room.Objects.Find(o=>o.Id==ice[0].Id))==expected&&state.ObjectStates[ice[0].Id].solid==(expected=="cold"),"Retry resetPolicy "+policy);}
            {var raw=(JObject)project.OriginalJson.DeepClone();foreach(JObject c in (JArray)raw["courses"])foreach(JObject room in (JArray)c["rooms"])if((string)room["id"]==g.Room.Id){foreach(JObject zone in (JArray)room["zones"])zone["initial"]="cold";((JArray)room["zones"]).Add(new JObject{{"id","test-overlap-hot"},{"x",ice[0].X},{"y",ice[0].Y},{"w",1},{"h",1},{"initial","hot"}});}var state=Intro(NativeProjectLoader.LoadBytes(Encoding.UTF8.GetBytes(raw.ToString()),"json",new ImportOptions{Profile=ImportProfile.EditorAuto}));var overlap=state.Room.Objects.Find(o=>o.Id==ice[0].Id);Check(state.TemperatureAt(overlap)=="hot"&&!state.ObjectStates[overlap.Id].solid,"hot overlap wins against cold zone");}
            return n;
        }
    }
}
